leSentence":{"en":"The primary challenge is fundraising.","jp":"第一の課題は資金調達だ。"}},{"english":"amusement park / theme park","reading":"ゆうえんち","japanese":"遊園地","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"We went to an amusement park with our family on the weekend.","jp":"週末に家族で遊園地へ行きました。"}},{"english":"move","reading":"ひっこす","japanese":"引っ越す","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I''m moving to a new house next month.","jp":"来月、新しい家に引っ越します。"}},{"english":"pass / go through","reading":"とおる","japanese":"通る","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"Cars frequently pass on this road.","jp":"この道は車がよく通ります。"}},{"english":"turn off / extinguish / erase","reading":"けす","japanese":"消す","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"Please turn off the light.","jp":"電気を消してください。"}},{"english":"pray","reading":"いのる","japanese":"祈る","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To pray for peace.","jp":"平和を祈る。"}},{"english":"smell / sniff","reading":"かぐ","japanese":"嗅ぐ","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To smell the scent of a flower.","jp":"花の匂いを嗅ぐ。"}},{"english":"cut","reading":"きる","japanese":"切る","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To cut paper with scissors.","jp":"紙をハサミで切る。"}},{"english":"be troubled / be in difficulty","reading":"こまる","japanese":"困る","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I''m in trouble because I don''t have money.","jp":"お金がなくて困っています。"}},{"english":"turn / bend","reading":"まがる","japanese":"曲がる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"Please turn right at the next corner.","jp":"次の角を右に曲がってください。"}},{"english":"raise / bring up / cultivate","reading":"そだてる","japanese":"育てる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To raise children with care.","jp":"子供を大切に育てる。"}},{"english":"succeed","reading":"せいこうする","japanese":"成功する","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"The project was successfully completed.","jp":"プロジェクトは無事に成功した。"}},{"english":"ask / request / entrust","reading":"たのむ","japanese":"頼む","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I asked my friend for help.","jp":"友達に助けを頼んだ。"}},{"english":"shine / glitter / gleam","reading":"ひかる","japanese":"光る","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"The stars shine beautifully in the night sky.","jp":"星が夜空に美しく光る。"}},{"english":"cool / chill","reading":"ひやす","japanese":"冷やす","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I''ll chill the beer in the refrigerator.","jp":"ビールを冷蔵庫で冷やしておく。"}},{"english":"be thirsty","reading":"のどがかわく","japanese":"喉が渇く","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I''m thirsty, so I want something to drink.","jp":"喉が渇いたから、何か飲みたい。"}},{"english":"score / points / marks","reading":"てんすう","japanese":"点数","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"He got a good score on the exam.","jp":"彼は試験で良い点数を取った。"}},{"english":"hallway / corridor","reading":"ろうか","japanese":"廊下","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Do not run in the hallway.","jp":"廊下を走ってはいけません。"}},{"english":"once / one time / one round","reading":"いっかい","japanese":"一回","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Please take this medicine once a day.","jp":"この薬は1日1回飲んでください。"}},{"english":"coat / jacket / outerwear","reading":"うわぎ","japanese":"上着","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Please wear a jacket because it''s cold.","jp":"寒いので上着を着てください。"}},{"english":"bank","reading":"ぎんこう","japanese":"銀行","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Withdraw money at the bank.","jp":"銀行でお金を引き出す。"}},{"english":"singer","reading":"かしゅ","japanese":"歌手","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"She is a famous singer.","jp":"彼女は有名な歌手です。"}},{"english":"largest / greatest / maximum","reading":"さいだい","japanese":"最大","jlpt_level":"N5","partOfSpeech":"adjective","exampleSentence":{"en":"Make the greatest effort.","jp":"最大の努力をする。"}},{"english":"adult","reading":"おとな","japanese":"大人","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"He is already an adult.","jp":"彼はもう大人だ。"}},{"english":"shop assistant / store clerk / salesperson","reading":"てんいん","japanese":"店員","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"The shop assistant at that store is very kind.","jp":"あの店の店員さんはとても親切です。"}},{"english":"first child / firstborn","reading":"ひとりめのこ","japanese":"1人目の子","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Our first child is a girl.","jp":"私たちの1人目の子は女の子です。"}},{"english":"water bottle / canteen / flask","reading":"すいとう","japanese":"水筒","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I prepared by putting tea in my water bottle for the excursion.","jp":"遠足のために、水筒にお茶を入れて準備しました。"}},{"english":"all night long / all through the night / overnight","reading":"ひとばんじゅう","japanese":"一晩中","jlpt_level":"N5","partOfSpeech":"adverb","exampleSentence":{"en":"It was raining all night long last night.","jp":"昨晩は一晩中雨が降っていました。"}},{"english":"magic / sorcery","reading":"まほう","japanese":"魔法","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"He defeated his enemy using magic.","jp":"彼は魔法を使って敵を倒した。"}},{"english":"preparation / arrangement","reading":"じゅんび","japanese":"準備","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I need to make preparations for the trip.","jp":"旅行の準備をする必要があります。"}},{"english":"universe / cosmos / outer space","reading":"うちゅう","japanese":"宇宙","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"There are still many undiscovered stars in the universe.","jp":"宇宙にはまだ多くの未発見の星がある。"}},{"english":"heart / mind / spirit","reading":"こころ","japanese":"心","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"He has a kind heart.","jp":"彼の心は優しい。"}},{"english":"practice","reading":"れんしゅう","japanese":"練習","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"It''s important to practice every day.","jp":"毎日練習することが大切だ。"}},{"english":"music","reading":"おんがく","japanese":"音楽","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"He likes listening to music.","jp":"彼は音楽を聴くのが好きです。"}},{"english":"little by little / gradually","reading":"すこしずつ","japanese":"少しずつ","jlpt_level":"N5","partOfSpeech":"adverb","exampleSentence":{"en":"He is gradually improving his Japanese.","jp":"彼は少しずつ日本語が上達している。"}},{"english":"gold","reading":"きん","japanese":"金","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I will work hard aiming for a gold medal.","jp":"金メダルを目指して頑張ります。"}},{"english":"silver","reading":"ぎん","japanese":"銀","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I gave a silver necklace as a present.","jp":"銀のネックレスをプレゼントしました。"}},{"english":"reading / a read","reading":"よみ","japanese":"読み","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"What is the reading of this kanji?","jp":"この漢字の読みは何ですか？"}},{"english":"find","reading":"みつける","japanese":"見つける","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I found a treasure.","jp":"宝物を見つけた。"}},{"english":"japanese language","reading":"にほんご","japanese":"日本語","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I am studying Japanese.","jp":"私は日本語を勉強しています。"}},{"english":"word / language","reading":"ことば","japanese":"言葉","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I was moved by his words.","jp":"彼の言葉に感動した。"}},{"english":"eight","reading":"はち","japanese":"八","jlpt_level":"N5","partOfSpeech":"number","exampleSentence":{"en":"I live on the eighth floor.","jp":"八階に住んでいます。"}},{"english":"how much is this?","reading":"これはい・くら・ですか？","japanese":"これはいくらですか？","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Excuse me, how much is this T-shirt?","jp":"すみません、このTシャツはいくらですか？"}},{"english":"nine","reading":"きゅう","japanese":"九","jlpt_level":"N5","partOfSpeech":"number","exampleSentence":{"en":"I go to bed at nine o''clock.","jp":"九時に寝ます。"}},{"english":"thousand","reading":"せん","japanese":"千","jlpt_level":"N5","partOfSpeech":"number","exampleSentence":{"en":"A 1000-yen bill.","jp":"千円札。"}},{"english":"ten","reading":"じゅう","japanese":"十","jlpt_level":"N5","partOfSpeech":"number","exampleSentence":{"en":"He is ten years old.","jp":"彼は十歳です。"}},{"english":"hundred","reading":"ひゃく","japanese":"百","jlpt_level":"N5","partOfSpeech":"number","exampleSentence":{"en":"A 100-yen coin.","jp":"百円玉。"}},{"english":"he / him / boyfriend","reading":"かれ","japanese":"彼","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"He is my older brother.","jp":"彼は私の兄です。"}},{"english":"know / knowledge / wisdom","reading":"し-","japanese":"知","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"He knew that secret.","jp":"彼はその秘密を知っていた。"}},{"english":"still / as yet / not yet","reading":"いまだ","japanese":"未だ","jlpt_level":"N5","partOfSpeech":"adverb","exampleSentence":{"en":"He still hasn''t come.","jp":"彼は未だに来ない。"}},{"english":"during / in the middle of","reading":"ちゅう","japanese":"中","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I am in a meeting right now.","jp":"今、会議中です。"}},{"english":"how old are you?","reading":"なんさいですか？","japanese":"何歳ですか？","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Excuse me, what is your name and how old are you?","jp":"すみません、お名前と何歳ですか？"}},{"english":"know / be aware of / find out","reading":"しる","japanese":"知る","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I know that fact.","jp":"私はその事実を知っている。"}},{"english":"not / without / non-existent","reading":"ない","japanese":"ない","jlpt_level":"N5","partOfSpeech":"adjective","exampleSentence":{"en":"I won''t do my homework.","jp":"宿題をしない。"}},{"english":"sky","reading":"そら","japanese":"空","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"When I look up at the blue sky, my mind calms down.","jp":"青い空を見上げると、心が落ち着きます。"}},{"english":"number / amount","reading":"かず","japanese":"数","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Please count the number of participants in the meeting.","jp":"会議の参加者の数を数えてください。"}},{"english":"johnny","reading":"ジョニー","japanese":"ジョニー","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Johnny is good at playing the guitar.","jp":"ジョニーはギターを弾くのが得意だ。"}},{"english":"buy / purchase","reading":"か","japanese":"買","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"He went to buy a new book.","jp":"彼は新しい本を買いに行った。"}},{"english":"one / first / a bit","reading":"いち","japanese":"いち","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"Please give me one apple.","jp":"りんごをいちつください。"}},{"english":"good / nice / fine","reading":"いい","japanese":"いい","jlpt_level":"N5","partOfSpeech":"adjective","exampleSentence":{"en":"That''s a good idea, isn''t it?","jp":"それはいい考えですね。"}},{"english":"probably / i guess / i''m sure","reading":"しょう","japanese":"しょう","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"It will probably be sunny tomorrow.","jp":"明日は晴れるでしょう。"}},{"english":"ten thousand","reading":"まん","japanese":"万","jlpt_level":"N5","partOfSpeech":"number","exampleSentence":{"en":"Ten thousand yen.","jp":"一万円。"}},{"english":"yen / circle","reading":"えん","japanese":"円","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"This is 100 yen.","jp":"これは百円です。"}},{"english":"parent / parents / father","reading":"おや","japanese":"親","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"My parents always support me.","jp":"私の親はいつも私を応援してくれます。"}},{"english":"time / hour / o''clock","reading":"とき","japanese":"時","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"What time is it now?","jp":"今は何時ですか？"}},{"english":"minute / part / portion","reading":"ふん","japanese":"分","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"He will come in ten minutes.","jp":"彼は十分で来ます。"}},{"english":"later","reading":"あとで","japanese":"後で","jlpt_level":"N5","partOfSpeech":"adverb","exampleSentence":{"en":"I''ll call you later.","jp":"後で電話します。"}},{"english":"room","reading":"へや","japanese":"部屋","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"His room is very clean.","jp":"彼の部屋はとてもきれいです。"}},{"english":"road / path / way","reading":"みち","japanese":"道","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Where does this road go?","jp":"この道はどこへ行くのですか。"}},{"english":"child / children","reading":"こども","japanese":"子供","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"The children are playing in the park.","jp":"子供たちが公園で遊んでいます。"}},{"english":"country / nation","reading":"くに","japanese":"国","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"He loves his country.","jp":"彼は自分の国を愛しています。"}},{"english":"town / city","reading":"まち","japanese":"町","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"This town is very quiet.","jp":"この町はとても静かです。"}},{"english":"place","reading":"ところ","japanese":"所","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I found a good place.","jp":"良い所を見つけました。"}},{"english":"i","reading":"わたし","japanese":"私","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"I am Japanese.","jp":"私は日本人です。"}},{"english":"what","reading":"なに","japanese":"何","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"What is this?","jp":"これは何ですか？"}},{"english":"between / space / interval","reading":"あいだ","japanese":"間","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Between the desk and the chair.","jp":"机と椅子の間。"}},{"english":"who","reading":"だれ","japanese":"誰","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"Who came?","jp":"誰が来ましたか？"}},{"english":"side","reading":"がわ","japanese":"側","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Please look to the right side.","jp":"右側を見てください。"}},{"english":"near / nearby","reading":"ちかく","japanese":"近く","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I live near the station.","jp":"駅の近くに住んでいます。"}},{"english":"over there / beyond / the other side","reading":"むこう","japanese":"向こう","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"There''s a convenience store over there.","jp":"向こうにコンビニがあります。"}},{"english":"over there","reading":"あそこ","japanese":"あそこ","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"There''s something over there.","jp":"あそこに何かあります。"}},{"english":"there","reading":"そこ","japanese":"そこ","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"Please put the book there.","jp":"そこに本を置いてください。"}},{"english":"where","reading":"どこ","japanese":"どこ","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"Where is the station?","jp":"駅はどこですか？"}},{"english":"this way / here / this person","reading":"こちら","japanese":"こちら","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"Please come this way.","jp":"こちらへどうぞ。"}},{"english":"that way / over there / that person","reading":"あちら","japanese":"あちら","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"The restroom is over there.","jp":"お手洗いはあちらです。"}},{"english":"which way / where / which one of two","reading":"どちら","japanese":"どちら","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"Which one do you prefer?","jp":"どちらがお好きですか？"}},{"english":"when","reading":"いつ","japanese":"いつ","jlpt_level":"N5","partOfSpeech":"adverb","exampleSentence":{"en":"When did you go to Japan?","jp":"いつ日本へ行きましたか。"}},{"english":"then","reading":"そして","japanese":"そして","jlpt_level":"N5","partOfSpeech":"conjunction","exampleSentence":{"en":"She sang, and then danced.","jp":"彼女は歌った。そして、踊った。"}},{"english":"after that / then","reading":"それから","japanese":"それから","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I ate breakfast. After that, I went to work.","jp":"朝食を食べた。それから、仕事に行った。"}},{"english":"most / best / number one","reading":"いちばん","japanese":"一番","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I like her the most.","jp":"彼女が一番好きです。"}},{"english":"same / identical","reading":"おなじ","japanese":"同じ","jlpt_level":"N5","partOfSpeech":"adjective","exampleSentence":{"en":"We have the same opinion.","jp":"私たちは同じ意見です。"}},{"english":"large / big / great","reading":"だい","japanese":"大","jlpt_level":"N5","partOfSpeech":"adjective","exampleSentence":{"en":"This is a big problem.","jp":"これは大きな問題です。"}},{"english":"take out / put out / send out","reading":"だす","japanese":"出す","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To take out the trash from the room.","jp":"部屋からごみを出す。"}},{"english":"take / pick up / get","reading":"とる","japanese":"取る","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"Please take the book.","jp":"本を取ってください。"}},{"english":"play / hang out / visit","reading":"あそぶ","japanese":"遊ぶ","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"The children are playing in the park.","jp":"子供たちが公園で遊んでいる。"}},{"english":"swim","reading":"およぐ","japanese":"泳ぐ","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To swim in the pool.","jp":"プールで泳ぐ。"}},{"english":"finish / end","reading":"おわる","japanese":"終わる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"The meeting ends.","jp":"会議が終わる。"}},{"english":"forget / leave behind","reading":"わすれる","japanese":"忘れる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To forget one''s homework.","jp":"宿題を忘れる。"}},{"english":"remember / memorize / learn","reading":"おぼえる","japanese":"覚える","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To memorize new vocabulary.","jp":"新しい単語を覚える。"}},{"english":"think / consider / ponder","reading":"かんがえる","japanese":"考える","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To think carefully.","jp":"よく考える。"}},{"english":"cleaning","reading":"そうじ","japanese":"掃除","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"To clean the room.","jp":"部屋の掃除をする。"}},{"english":"laundry / washing","reading":"せんたく","japanese":"洗濯","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"To hang out the laundry.","jp":"洗濯物を干す。"}},{"english":"cooking / cuisine / dish","reading":"りょうり","japanese":"料理","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"To cook Japanese food.","jp":"日本料理を作る。"}},{"english":"sing","reading":"うたう","japanese":"歌う","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To sing a song.","jp":"歌を歌う。"}},{"english":"study","reading":"べんきょう","japanese":"勉強","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"To study Japanese.","jp":"日本語を勉強する。"}},{"english":"spirit / mind / mood","reading":"き","japanese":"気","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"To be careful.","jp":"気をつける。"}},{"english":"meaning / significance","reading":"いみ","japanese":"意味","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I don''t understand the meaning of this word.","jp":"この言葉の意味が分からない。"}},{"english":"homework","reading":"しゅくだい","japanese":"宿題","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"To do homework.","jp":"宿題をする。"}},{"english":"good morning","reading":"ō","japanese":"おはよう","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Good morning! Did you sleep well?","jp":"おはよう！よく眠れた？"}},{"english":"mark / score / point","reading":"てん","japanese":"点","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"She got good marks on the test.","jp":"彼女はテストで良い点を取った。"}},{"english":"breakfast","reading":"ちょうしょく","japanese":"朝食","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"From what time is breakfast served?","jp":"朝食は何時からですか？"}},{"english":"lunch","reading":"ちゅうしょく","japanese":"昼食","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Where will you have lunch?","jp":"昼食はどこで食べますか？"}},{"english":"stuff","reading":"もの","japanese":"物","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"There''s a lot of stuff in that box.","jp":"その箱にはたくさんの物が入っています。"}},{"english":"deer","reading":"しか","japanese":"シカ","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"There are many deer in Nara Park.","jp":"奈良公園にはたくさんのシカがいます。"}},{"english":"low / short / humble","reading":"ひくい","japanese":"低い","jlpt_level":"N5","partOfSpeech":"adjective","exampleSentence":{"en":"This desk is a bit too low.","jp":"この机は少し低すぎる。"}},{"english":"neighborhood / vicinity","reading":"きんじょ","japanese":"近所","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"A new bakery opened in the neighborhood, so I often go there.","jp":"近所に新しいパン屋さんができたので、よく行きます。"}},{"english":"sugar","reading":"さとう","japanese":"砂糖","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Do you put sugar in your coffee?","jp":"コーヒーに砂糖を入れますか？"}},{"english":"dictionary","reading":"じしょ","japanese":"辞書","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I bought a new dictionary.","jp":"新しい辞書を買いました。"}},{"english":"blackboard / chalkboard","reading":"こくばん","japanese":"黒板","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"The teacher wrote characters on the blackboard.","jp":"先生が黒板に字を書いた。"}},{"english":"warm","reading":"あたたかい","japanese":"暖かい","jlpt_level":"N5","partOfSpeech":"adjective","exampleSentence":{"en":"Today is a very warm day.","jp":"今日はとても暖かい日だ。"}},{"english":"shinto shrine","reading":"じんじゃ","japanese":"神社","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I went to the local shrine for the New Year''s visit.","jp":"初詣に地元の神社へ行った。"}},{"english":"hot spring / spa","reading":"おんせん","japanese":"温泉","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"There are many beautiful hot springs in Japan.","jp":"日本には美しい温泉がたくさんあります。"}},{"english":"hairstyle / hairdo","reading":"かみがた","japanese":"髪型","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"She got a new hairstyle.","jp":"彼女は新しい髪型にした。"}},{"english":"grandfather","reading":"そふ","japanese":"祖父","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"My grandfather was a very kind person.","jp":"私の祖父はとても優しい人でした。"}},{"english":"grandmother","reading":"そぼ","japanese":"祖母","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"My grandmother''s cooking is always delicious.","jp":"祖母の料理はいつも美味しい。"}},{"english":"classroom","reading":"きょうしつ","japanese":"教室","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"After school, we did our homework in the classroom.","jp":"放課後、私たちは教室で宿題をしました。"}},{"english":"afternoon","reading":"ごご","japanese":"午後","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"The meeting starts at 3 in the afternoon.","jp":"会議は午後3時に始まります。"}},{"english":"morning","reading":"ごぜん","japanese":"午前","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I jog every morning.","jp":"私は毎朝午前中にジョギングをします。"}},{"english":"character / letter / script","reading":"もじ","japanese":"文字","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"How do you read this character?","jp":"この文字はなんて読みますか？"}},{"english":"giraffe","reading":"キリン","japanese":"キリン","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I saw a giraffe at the zoo.","jp":"動物園でキリンを見ました。"}},{"english":"address","reading":"じゅうしょ","japanese":"住所","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Please tell me your address.","jp":"住所を教えてください。"}},{"english":"environment / surroundings / circumstances","reading":"かんきょう","japanese":"環境","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"We need to protect the Earth''s environment.","jp":"私たちは地球の環境を守る必要があります。"}},{"english":"hot water","reading":"おゆ","japanese":"お湯","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Let''s boil some hot water to make tea.","jp":"お茶を淹れるためにお湯を沸かしましょう。"}},{"english":"bloom / blossom","reading":"さく","japanese":"咲く","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"The cherry blossoms bloomed beautifully.","jp":"桜が美しく咲いた。"}},{"english":"number / figure / digit","reading":"すうじ","japanese":"数字","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"All the numbers in this table are accurate.","jp":"この表の数字はすべて正確です。"}},{"english":"many","reading":"たくさん","japanese":"たくさん","jlpt_level":"N5","partOfSpeech":"adverb","exampleSentence":{"en":"I studied a lot.","jp":"たくさん勉強した。"}},{"english":"home / household / family","reading":"かてい","japanese":"家庭","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"She wants to build a warm home/family.","jp":"彼女は温かい家庭を築きたいと思っている。"}},{"english":"don''t know / don''t understand / cannot understand","reading":"わからない","japanese":"わからない","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I don''t understand what he''s saying.","jp":"彼の言っていることがわからない。"}},{"english":"myself / oneself / yourself","reading":"じぶん","japanese":"自分","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I''ll do my own things myself.","jp":"自分のことは自分でやる。"}},{"english":"you","reading":"あなた","japanese":"あなた","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"What is your name?","jp":"あなたの名前は何ですか。"}},{"english":"say / tell","reading":"いう","japanese":"言う","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"He didn''t say anything.","jp":"彼は何も言わなかった。"}},{"english":"people","reading":"ひとたち","japanese":"人たち","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"There were many people there.","jp":"そこにはたくさんの人たちがいた。"}},{"english":"don''t know / unaware","reading":"しらない","japanese":"知らない","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I don''t know that fact.","jp":"私はその事実を知らない。"}},{"english":"night","reading":"よる","japanese":"夜","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I slept well tonight.","jp":"今夜はよく眠れた。"}},{"english":"moreover / not only... but also / because","reading":"し","japanese":"し","jlpt_level":"N5","partOfSpeech":"particle","exampleSentence":{"en":"He''s kind, and he''s interesting, I really like him.","jp":"彼は優しいし、面白いし、とても好きです。"}},{"english":"but / although / however","reading":"けど","japanese":"けど","jlpt_level":"N5","partOfSpeech":"particle","exampleSentence":{"en":"I want to go, but I don''t have time.","jp":"行きたいけど、時間がない。"}},{"english":"airplane / aircraft","reading":"ひこうき","japanese":"飛行機","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I rode an airplane for the first time.","jp":"初めて飛行機に乗りました。"}},{"english":"green","reading":"みどりいろ","japanese":"緑色","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"This leaf is a vivid green color.","jp":"この葉っぱは鮮やかな緑色をしている。"}},{"english":"various","reading":"いろいろ","japanese":"色々","jlpt_level":"N5","partOfSpeech":"adjective","exampleSentence":{"en":"I visited various places over the weekend.","jp":"週末は色々な場所を訪れました。"}},{"english":"how are you?","reading":"おげんきですか？","japanese":"お元気ですか？","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Hello, Mr. Tanaka. How are you?","jp":"こんにちは、田中さん。お元気ですか？"}},{"english":"open / hold","reading":"ひらく","japanese":"開く","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"Please open the book and read.","jp":"本を開いて読んでください。"}},{"english":"change / vary","reading":"かわる","japanese":"変わる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"The scenery changes with the seasons.","jp":"季節によって景色が変わる。"}},{"english":"if do","reading":"すれば","japanese":"すれば","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"If you study more, you can pass the exam.","jp":"もっと勉強すれば、試験に合格できる。"}},{"english":"fit","reading":"あう","japanese":"合う","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"These clothes suit me.","jp":"この服は私に合っている。"}},{"english":"that way / there / that person","reading":"そちら","japanese":"そちら","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"What''s your opinion on that?","jp":"そちらの意見はどうですか？"}},{"english":"dance","reading":"おどる","japanese":"踊る","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"To dance to the music.","jp":"音楽に合わせて踊る。"}},{"english":"dinner / supper","reading":"ゆうしょく","japanese":"夕食","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Dinner is ready.","jp":"夕食の準備ができました。"}},{"english":"physical condition","reading":"たいちょう","japanese":"体調","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I''m not feeling well, so I''ll take a day off today.","jp":"体調が優れないので、今日は休みます。"}},{"english":"errand / business / things to do","reading":"ようじ","japanese":"用事","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I have an urgent errand today.","jp":"今日は急な用事があります。"}},{"english":"father","reading":"ちち","japanese":"父","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"My father is a doctor.","jp":"私の父は医者です。"}},{"english":"mother","reading":"はは","japanese":"母","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"My mother cooks every day.","jp":"私の母は毎日料理します。"}},{"english":"older brother","reading":"あに","japanese":"兄","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"My older brother is a university student.","jp":"私の兄は大学生です。"}},{"english":"older sister","reading":"あね","japanese":"姉","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"My older sister plays the piano.","jp":"私の姉はピアノを弾きます。"}},{"english":"younger brother","reading":"おとうと","japanese":"弟","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"My younger brother is a high school student.","jp":"私の弟は高校生です。"}},{"english":"younger sister","reading":"いもうと","japanese":"妹","jlpt_level":"N5","partOfSpeech":"noun","ex