exampleSentence":{"en":"I go on a trip every year.","jp":"まいねん旅行に行きます。"}},{"english":"every evening","reading":"まいばん","japanese":"まいばん","jlpt_level":"N5","partOfSpeech":"adverb","exampleSentence":{"en":"I watch TV every evening.","jp":"まいばんテレビを見ます。"}},{"english":"straight","reading":"まっすぐ","japanese":"まっすぐ","jlpt_level":"N5","partOfSpeech":"adverb","exampleSentence":{"en":"Please go straight.","jp":"まっすぐ行ってください。"}},{"english":"brush","reading":"みがく","japanese":"みがく","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I brush my teeth every night.","jp":"毎晩歯をみがきます。"}},{"english":"show","reading":"みせる","japanese":"みせる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"Please show me your passport.","jp":"パスポートをみせてください。"}},{"english":"three","reading":"みっつ","japanese":"みっつ","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Please give me three apples.","jp":"りんごをみっつください。"}},{"english":"apple","reading":"りんご","japanese":"りんご","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"This apple is delicious.","jp":"このリンゴは美味しい。"}},{"english":"refrigerator","reading":"れいぞうこ","japanese":"れいぞうこ","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"There is milk in the refrigerator.","jp":"冷蔵庫に牛乳があります。"}},{"english":"um","reading":"あのう","japanese":"あのう","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Um, excuse me.","jp":"あのう、すみません。"}},{"english":"thank you","reading":"ありがとうございます","japanese":"ありがとうございます","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Thank you for helping me.","jp":"手伝ってくれて、ありがとうございます。"}},{"english":"i''m leaving","reading":"いってきます","japanese":"いってきます","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"I''m leaving!","jp":"いってきます！"}},{"english":"welcome","reading":"いらっしゃいませ","japanese":"いらっしゃいませ","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Welcome.","jp":"いらっしゃいませ。"}},{"english":"yes","reading":"ええ","japanese":"ええ","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Yes, that''s right.","jp":"ええ、そうです。"}},{"english":"eh","reading":"えー","japanese":"えー","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Eh, really?","jp":"えー、本当ですか。"}},{"english":"what?","reading":"えっ","japanese":"えっ","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"What? Is it already over?","jp":"えっ、もう終わりですか。"}},{"english":"please","reading":"おねがいします","japanese":"おねがいします","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"One more cup, please.","jp":"もう一杯、お願いします。"}},{"english":"good morning","reading":"おはようございます","japanese":"おはようございます","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Good morning.","jp":"おはようございます。"}},{"english":"good night","reading":"おやすみなさい","japanese":"おやすみなさい","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Good night.","jp":"おやすみなさい。"}},{"english":"thank you for the meal","reading":"ごちそうさまでした","japanese":"ごちそうさまでした","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Thank you for the meal.","jp":"ごちそうさまでした。"}},{"english":"sorry","reading":"ごめんなさい","japanese":"ごめんなさい","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Sorry I''m late.","jp":"遅れてごめんなさい。"}},{"english":"hello","reading":"こんにちは","japanese":"こんにちは","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Hello. How are you?","jp":"こんにちは。お元気ですか。"}},{"english":"good evening","reading":"こんばんは","japanese":"こんばんは","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Good evening. Are you having dinner now?","jp":"こんばんは。今から夕食ですか。"}},{"english":"goodbye","reading":"さようなら","japanese":"さようなら","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Goodbye. Let''s meet again.","jp":"さようなら。また会いましょう。"}},{"english":"excuse me","reading":"すみません","japanese":"すみません","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Excuse me, where is the station?","jp":"すみません、駅はどこですか。"}},{"english":"i''m home","reading":"ただいま","japanese":"ただいま","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"I''m back home.","jp":"ただいま戻りました。"}},{"english":"you''re welcome","reading":"どういたしまして","japanese":"どういたしまして","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Thank you. You''re welcome.","jp":"ありがとう。どういたしまして。"}},{"english":"thank you very much","reading":"どうもありがとう","japanese":"どうもありがとう","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"You really helped me. Thank you very much.","jp":"助かりました。どうもありがとう。"}},{"english":"nice to meet you","reading":"はじめまして","japanese":"はじめまして","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Nice to meet you. I''m Tanaka. Please treat me well.","jp":"はじめまして。田中です。よろしくお願いします。"}},{"english":"everyone","reading":"みんな","japanese":"みんな","jlpt_level":"N5","partOfSpeech":"pronoun","exampleSentence":{"en":"Is everyone well?","jp":"みんな、元気ですか。"}},{"english":"welcome home","reading":"おかえりなさい","japanese":"おかえりなさい","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Welcome home, it''s good you''re back.","jp":"おかえりなさい、よく来たね。"}},{"english":"let''s eat","reading":"いただきます","japanese":"いただきます","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Let''s eat! It looks delicious.","jp":"いただきます！美味しいそうですね。"}},{"english":"have a good trip","reading":"いってらっしゃい","japanese":"いってらっしゃい","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"Have a good trip! Be careful.","jp":"いってらっしゃい！気をつけてね。"}},{"english":"snack","reading":"おやつ","japanese":"おやつ","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"The child is asking for a snack.","jp":"子供がおやつを欲しがっています。"}},{"english":"how old","reading":"なんさい","japanese":"さい","jlpt_level":"N5","partOfSpeech":"phrase","exampleSentence":{"en":"How old are you?","jp":"あなたは何歳ですか？"}},{"english":"noon","reading":"しょうご","japanese":"しょうご","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"Let''s meet at the restaurant at noon.","jp":"正午にレストランで会いましょう。"}},{"english":"new Year","reading":"しょうがつ","japanese":"しょうがつ","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I will return to my hometown for the New Year.","jp":"正月は故郷に帰省します。"}},{"english":"wake up","reading":"めがさめる","japanese":"目が覚める","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I woke up early in the morning.","jp":"朝早く目が覚めた。"}},{"english":"hungry","reading":"おなかがすく","japanese":"お腹が空く","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I''m hungry, so I want to eat something.","jp":"お腹が空いたので、何か食べたい。"}},{"english":"full","reading":"おなかいっぱい","japanese":"お腹がいっぱい","jlpt_level":"N5","partOfSpeech":"adjective","exampleSentence":{"en":"I ate a lot, so I am full.","jp":"たくさん食べたので、お腹がいっぱいです。"}},{"english":"sleepy","reading":"ねむくなる","japanese":"眠くなる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I became sleepy during class in the afternoon.","jp":"午後、授業中に眠くなった。"}},{"english":"healthy","reading":"げんきになる","japanese":"元気になる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I was sick, but I am getting better now.","jp":"病気だったが、もう元気になる。"}},{"english":"sick","reading":"びょうきになる","japanese":"病気になる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I caught a cold and became sick.","jp":"風邪をひいて病気になった。"}},{"english":"adult","reading":"おとなになる","japanese":"大人になる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I want to become an adult quickly.","jp":"早く大人になりたい。"}},{"english":"teacher","reading":"せんせいになる","japanese":"先生になる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I want to become a teacher in the future.","jp":"将来、先生になりたいです。"}},{"english":"doctor","reading":"いしゃになる","japanese":"医者になる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"He dreams of becoming a doctor.","jp":"彼は医者になることを夢見ている。"}},{"english":"rain","reading":"あめがふる","japanese":"雨が降る","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"If you don''t have an umbrella, you''ll be in trouble if it rains.","jp":"傘がないと、雨が降ったら困る。"}},{"english":"wind","reading":"かぜがふく","japanese":"風が吹く","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"The wind is blowing strongly today.","jp":"今日は風が強く吹いている。"}},{"english":"spring","reading":"はるがくる","japanese":"春が来る","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"When spring comes, flowers begin to bloom.","jp":"春が来ると、花が咲き始める。"}},{"english":"summer","reading":"なつになる","japanese":"夏になる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"It will be summer soon, won''t it?","jp":"すぐに夏になりますね。"}},{"english":"autumn","reading":"あきになる","japanese":"秋になる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"The hot days continue, and there''s no sign of autumn.","jp":"暑い日が続き、秋になる気配がない。"}},{"english":"winter","reading":"ふゆになる","japanese":"冬になる","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"Winter will be here soon.","jp":"もうすぐ冬になります。"}},{"english":"bloom","reading":"はながさく","japanese":"花が咲く","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"Beautiful flowers bloomed in the garden.","jp":"庭にきれいな花が咲いた。"}},{"english":"sweat","reading":"あせをかく","japanese":"汗をかく","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I exercised and sweated.","jp":"運動して汗をかいた。"}},{"english":"cough","reading":"せきをする","japanese":"咳をする","jlpt_level":"N5","partOfSpeech":"verb","exampleSentence":{"en":"I have a cold and can''t stop coughing.","jp":"風邪をひいて咳が止まらない。"}},{"english":"travel / trip","reading":"りょこう","japanese":"旅行","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"I plan to go on a trip in the summer.","jp":"夏に旅行に行く予定です。"}},{"english":"japanese person","reading":"にほんじん","japanese":"日本人","jlpt_level":"N5","partOfSpeech":"noun","exampleSentence":{"en":"He is a Japanese person.","jp":"彼は日本人です。"}},{"english":"word / vocabulary","reading":"たんご","japa