tence":{"en":"The water is gradually disappearing.","jp":"水がだんだん無くなってきた。"}},{"english":"diary","reading":"にっき","japanese":"日記","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"I keep a diary every day.","jp":"毎日日記をつけています。"}},{"english":"enrollment","reading":"にゅうがく","japanese":"入学","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"I enrolled in university this year.","jp":"今年、大学に入学しました。"}},{"english":"paint","reading":"ぬる","japanese":"塗る","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"I painted the wall with paint.","jp":"壁にペンキを塗りました。"}},{"english":"get wet","reading":"ぬれる","japanese":"濡れる","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"My clothes got wet in the rain.","jp":"雨で服が濡れてしまった。"}},{"english":"oversleeping","reading":"ねぼう","japanese":"寝坊","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"I overslept and was late.","jp":"寝坊して遅刻した。"}},{"english":"remain","reading":"のこる","japanese":"残る","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"Food remains on the table.","jp":"食べ物がテーブルに残っている。"}},{"english":"throat","reading":"のど","japanese":"喉","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"I was thirsty, so I drank water.","jp":"喉が渇いたので水を飲んだ。"}},{"english":"change trains","reading":"のりかえる","japanese":"乗り換える","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"I will change trains at Tokyo Station.","jp":"東京駅で電車を乗り換えます。"}},{"english":"vehicle","reading":"のりもの","japanese":"乗り物","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Children like various vehicles.","jp":"子供は色々な乗り物が好きだ。"}},{"english":"dentist","reading":"はいしゃ","japanese":"歯医者","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"I went to the dentist because I had a cavity.","jp":"虫歯があるので歯医者に行った。"}},{"english":"embarrassing","reading":"はずかしい","japanese":"恥ずかしい","jlpt_level":"N4","partOfSpeech":"adjective","exampleSentence":{"en":"Speaking in front of people is embarrassing.","jp":"人前で話すのは恥ずかしいです。"}},{"english":"drawer","reading":"ひきだし","japanese":"引き出し","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Please open the desk drawer.","jp":"机の引き出しを開けてください。"}},{"english":"long time no see","reading":"ひさしぶり","japanese":"久しぶり","jlpt_level":"N4","partOfSpeech":"adverb","exampleSentence":{"en":"Long time no see! How have you been?","jp":"久しぶりですね！お元気でしたか。"}},{"english":"be surprised","reading":"びっくりする","japanese":"びっくりする","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"I was surprised by the sudden noise.","jp":"突然の音にびっくりしました。"}},{"english":"daytime","reading":"ひるま","japanese":"昼間","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"It is very hot during the daytime.","jp":"昼間はとても暑いです。"}},{"english":"gain weight","reading":"ふとる","japanese":"太る","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"I ate too much and gained weight.","jp":"食べ過ぎて太ってしまいました。"}},{"english":"strange / odd","reading":"へん","japanese":"変","jlpt_level":"N4","partOfSpeech":"adjective","exampleSentence":{"en":"That person is a little strange.","jp":"あの人は少し変だ。"}},{"english":"almost","reading":"ほとんど","japanese":"ほとんど","jlpt_level":"N4","partOfSpeech":"adverb","exampleSentence":{"en":"My homework is almost finished.","jp":"宿題はほとんど終わりました。"}},{"english":"go / come","reading":"まいる","japanese":"参る","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"I will come to the office tomorrow (humble).","jp":"明日、会社に参ります。"}},{"english":"lose","reading":"まける","japanese":"負ける","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"I lost the game.","jp":"試合に負けた。"}},{"english":"first","reading":"まず","japanese":"まず","jlpt_level":"N4","partOfSpeech":"adverb","exampleSentence":{"en":"First, please wash your hands.","jp":"まず、手を洗ってください。"}},{"english":"or","reading":"または","japanese":"または","jlpt_level":"N4","partOfSpeech":"conjunction","exampleSentence":{"en":"Coffee or tea, which would you like?","jp":"コーヒーまたは紅茶、どちらにしますか。"}},{"english":"make a mistake / err","reading":"まちがえる","japanese":"間違える","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"I made a mistake with the kanji.","jp":"漢字を間違えてしまった。"}},{"english":"lake","reading":"みずうみ","japanese":"湖","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"That lake is very beautiful.","jp":"あの湖はとてもきれいです。"}},{"english":"be found / be discovered","reading":"みつかる","japanese":"見つかる","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"The lost key was found.","jp":"なくした鍵が見つかった。"}},{"english":"everyone / all","reading":"みな","japanese":"皆","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Hello everyone.","jp":"皆さん、こんにちは。"}},{"english":"olden days / former times","reading":"むかし","japanese":"昔","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Long ago, there was a big tree here.","jp":"昔、ここに大きな木があった。"}},{"english":"rare / unusual","reading":"めずらしい","japanese":"珍しい","jlpt_level":"N4","partOfSpeech":"adjective","exampleSentence":{"en":"This is a rare stamp.","jp":"これは珍しい切手です。"}},{"english":"soon","reading":"もうすぐ","japanese":"もうすぐ","jlpt_level":"N4","partOfSpeech":"adverb","exampleSentence":{"en":"The train will come soon.","jp":"電車がもうすぐ来ます。"}},{"english":"if","reading":"もし","japanese":"もし","jlpt_level":"N4","partOfSpeech":"conjunction","exampleSentence":{"en":"If it rains, I will stay home.","jp":"もし雨が降ったら、家にいます。"}},{"english":"return","reading":"もどる","japanese":"もどる","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"Return home early.","jp":"家に早くもどる。"}},{"english":"burn","reading":"やく","japanese":"やく","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"The bread is burning.","jp":"パンがやく。"}},{"english":"promise","reading":"やくそく","japanese":"やくそく","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Keep a promise.","jp":"やくそくを守る。"}},{"english":"finally","reading":"やっと","japanese":"やっと","jlpt_level":"N4","partOfSpeech":"adverb","exampleSentence":{"en":"Finally, the homework is finished.","jp":"やっと宿題が終わった。"}},{"english":"quit","reading":"やめる","japanese":"やめる","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"Quit smoking.","jp":"タバコをやめる。"}},{"english":"way","reading":"よう","japanese":"よう","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Please do it that way.","jp":"そのようにお願いします。"}},{"english":"preparation","reading":"ようい","japanese":"ようい","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Make preparations for the trip.","jp":"旅行のよういをする。"}},{"english":"errand","reading":"ようじ","japanese":"ようじ","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Go out on an errand.","jp":"ようじで外出する。"}},{"english":"plan","reading":"よてい","japanese":"よてい","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Make a plan for tomorrow.","jp":"明日のよていを立てる。"}},{"english":"reservation","reading":"よやく","japanese":"よやく","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Make a reservation at a restaurant.","jp":"レストランをよやくする。"}},{"english":"be happy","reading":"よろこぶ","japanese":"よろこぶ","jlpt_level":"N4","partOfSpeech":"verb","exampleSentence":{"en":"I was happy to pass the exam.","jp":"合格してよろこんだ。"}},{"english":"reason","reading":"りゆう","japanese":"りゆう","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Please tell me the reason.","jp":"そのりゆうを教えてください。"}},{"english":"absence","reading":"るす","japanese":"留守","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Someone visited while I was out.","jp":"私が留守の間に、誰かが訪ねてきた。"}},{"english":"cooling","reading":"れいぼう","japanese":"冷房","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"Cooling is indispensable in summer.","jp":"夏は冷房が欠かせない。"}},{"english":"history","reading":"れきし","japanese":"歴史","jlpt_level":"N4","partOfSpeech":"noun","exampleSentence":{"en":"I am studying Japanese history.","jp":"日本の歴史を勉強している。"}},{"english":"part","reading":"わかれる","japanese":"別れる",